function validate([nums, pattern]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100) return 'nums needs 2 to 100 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each value of nums is an integer from 1 to 10^9.';
  if (!Array.isArray(pattern) || pattern.length < 1 || pattern.length >= nums.length) return 'pattern needs at least 1 value and fewer values than nums.';
  if (pattern.some(v => v !== -1 && v !== 0 && v !== 1)) return 'Each value of pattern is -1, 0 or 1.';
  return null;
}

