function countMatchingSubarrays(nums, pattern) {
  const n = nums.length;
  const m = pattern.length;
  let count = 0;

  for (let start = 0; start + m < n; start++) {
    let matches = true;
    for (let k = 0; k < m; k++) {
      const trend = Math.sign(nums[start + k + 1] - nums[start + k]);
      if (trend !== pattern[k]) {
        matches = false;
        break;
      }
    }
    if (matches) {
      count++;
    }
  }
  return count;
}

