function countMatchingSubarrays(nums, pattern) {
  // Spell every step of nums and the pattern as letters, then count where the pattern text occurs.
  const letter = (code) => (code > 0 ? 'u' : code < 0 ? 'd' : 'e');
  let steps = '';
  for (let i = 1; i < nums.length; i++) {
    if (nums[i] > nums[i - 1]) steps += 'u';
    else if (nums[i] < nums[i - 1]) steps += 'd';
    else steps += 'e';
  }
  const wanted = pattern.map(letter).join('');
  let total = 0;
  for (let i = 0; i + wanted.length <= steps.length; i++) {
    if (steps.startsWith(wanted, i)) total++;
  }
  return total;
}

