function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 100 : int(2, 9);
  // Narrow value ranges make equal neighbours (pattern 0) common.
  const top = [3, 5, 1000, 1000000000][int(0, 3)];
  const nums = Array.from({ length: n }, () => int(1, top));
  const m = size === 'large' ? (rand() < 0.7 ? int(1, 5) : int(1, n - 1)) : int(1, n - 1);
  let pattern;
  if (rand() < 0.6) {
    // Copy the trend of a real window so that at least one match exists.
    const start = int(0, n - 1 - m);
    pattern = Array.from({ length: m }, (_, k) => Math.sign(nums[start + k + 1] - nums[start + k]));
  } else {
    pattern = Array.from({ length: m }, () => int(-1, 1));
  }
  return [nums, pattern];
}
